// Extraer texto de la respuesta de Claude
const text = $input.first().json.content[0].text;

// Claude a veces envuelve el JSON en bloques markdown — limpiar
const jsonMatch = text.match(/\{[\s\S]*\}/);
if (!jsonMatch) {
  throw new Error('Claude no devolvió JSON válido. Raw: ' + text.slice(0, 200));
}

const data = JSON.parse(jsonMatch[0]);

// Agregar fecha de hoy
data.fecha = new Date().toISOString().slice(0, 10);

// Validaciones básicas
if (!data.top3 || data.top3.length !== 3) {
  throw new Error('top3 inválido: ' + JSON.stringify(data.top3));
}
if (!data.tendencias || data.tendencias.length !== 3) {
  throw new Error('tendencias inválido: ' + JSON.stringify(data.tendencias));
}

const payload = JSON.stringify(data);

// Upstash REST API espera un JSON array como body en el root endpoint
// Lo stringificamos acá para mandarlo como raw body y evitar que n8n lo envuelva
const upstashBody = JSON.stringify(["SET", "noticias:diarias", payload, "EX", "90000"]);

return [{ json: { upstashBody, fecha: data.fecha } }];
